diff --git a/calendar/base/content/calendar-base-view.js b/calendar/base/content/calendar-base-view.js
index b81a47297b8..42c716ce1ca 100644
--- a/calendar/base/content/calendar-base-view.js
+++ b/calendar/base/content/calendar-base-view.js
@@ -262,11 +262,14 @@

       this.setAttribute("type", this.type);

-      window.addEventListener("viewresize", () => {
-        if (gCurrentMode == "calendar" && this.isVisible()) {
+      const resizeObserver = new ResizeObserver(entries => {
+        // If this view is visible in the last entry, resize.
+        const size = entries.at(-1).contentBoxSize[0];
+        if (size.blockSize && size.inlineSize) {
           this.onResize();
         }
       });
+      resizeObserver.observe(this);
       window.addEventListener("uifontsizechange", () => {
         this.onFontSizeChange();
       });
